```python
import json
from datetime import datetime

class CustomJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, (datetime)):
            return obj.isoformat()
        return super().default(obj)

class RegistryBasedFactory():

    _registry = {}
    _loaded_modules = set()

    @classmethod
    def register(cls, id):
        def registrar(subcls):
            cls._registry[id] = subcls
            return subcls
        return registrar

    @classmethod
    def create(cls, id, *args, **kwargs):
        if id not in cls._loaded_modules:
            cls.load_module(id)

        if id not in cls._registry:
            raise ValueError('Bad factory ID {}'.format(id))

        return cls._registry[id](*args, **kwargs)

    @classmethod
    def load_module(cls, module):
        __import__(module)
        cls._loaded_modules.add(module)

class MyClass(RegistryBasedFactory):

    @staticmethod
    def to_json(obj):
        return json.dumps(obj.__dict__, cls=CustomJSONEncoder)

    @classmethod
    def from_json(cls, data):
        fields = json.loads(data)

        if 'factory' not in fields:
            raise ValueError('No factory ID found')

        id = fields['factory']
        del fields['factory']

        return cls.create(id, **fields)
```

