from flask import Flask, request, jsonify
from pymongo import MongoClient
import redis
import requests
import time
from functools import wraps
from schema import Schema, And, Use, Optional

app = Flask(__name__)
mongo_client = MongoClient('mongodb://localhost:27017/')
db = mongo_client['user_profiles']
redis_cache = redis.Redis(host='localhost', port=6379)
oauth2_url = 'http://example.com/oauth2'  # replace with your oauth2 server url
schema = Schema({
    Optional('name'): And(str, len),
    Optional('email'): And(Use(str)),
})
rate_limits = {}
MAX_REQUESTS_PER_MIN = 100  # adjust as needed

def authenticate(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        response = requests.get(oauth2_url + '/verify', headers={'Authorization': token})
        if response.status_code != 200:
            return jsonify({'error': 'invalid credentials'}), 403
        kwargs['user'] = response.json()
        return func(*args, **kwargs)
    return wrapper

@app.route('/profile/<id>', methods=['PUT', 'DELETE'])
@authenticate
def manage_profiles(id, user):
    if request.method == 'PUT':
        return update_profile(id, user)
    elif request.method == 'DELETE':
        return delete_profile(id, user)

def update_profile(id, user):
    timestamp = time.time()
    if rate_limits.get(user['username'], 0) >= MAX_REQUESTS_PER_MIN:
        return jsonify({'error': 'rate limit exceeded'}), 429
    rate_limits[user['username']] = rate_limits.get(user['username'], -1) + 1
    try:
        data = schema.validate(request.json)
    except Exception as e:
        return jsonify({'error': str(e)}), 400
    profile = db['profiles'].find_one({'_id': id})
    if not profile:
        return jsonify({'error': 'profile not found'}), 404
    elif profile.get('version', -1) > request.json.get('version', -2):
        return jsonify({'error': 'conflict detected'}), 409
    db['profiles'].update_one({'_id': id, 'version': profile['version']}, {'$set': data, '$inc': {'version': 1}}, upsert=False)
    redis_cache.delete(f'profile:{id}')  # invalidate cache on update
    app.logger.info({'user': user['username'], 'action': 'update', 'timestamp': timestamp, 'data': data})
    return jsonify({'status': 'updated'}), 200

def delete_profile(id, user):
    timestamp = time.time()
    if rate_limits.get(user['username'], 0) >= MAX_REQUESTS_PER_MIN:
        return jsonify({'error': 'rate limit exceeded'}), 429
    rate_limits[user['username']] = rate_limits.get(user['username'], -1) + 1
    profile = db['profiles'].find_one({'_id': id})
    if not profile:
        return jsonify({'error': 'profile not found'}), 404
    elif profile.get('version', -1) > request.json.get('version', -2):
        return jsonify({'error': 'conflict detected'}), 409
    db['profiles'].delete_one({'_id': id, 'version': profile['version']})
    redis_cache.delete(f'profile:{id}')  # invalidate cache on delete
    app.logger.info({'user': user['username'], 'action': 'delete', 'timestamp': timestamp, 'data': None})
    return jsonify({'status': 'deleted'}), 200
```
