```python
import csv
import json
import xmltodict
import logging
from multiprocessing import Pool
from queue import Queue

class DataProcessor:
    def __init__(self):
        self.file_parsers = {
            'csv': self._parse_csv,
            'json': self._parse_json,
            'xml': self._parse_xml
        }
        self.logger = logging.getLogger(__name__)

    def _validate(self, data):
        # perform some validation on the data here
        pass

    def process(self, filepath):
        _, ext = filepath.rsplit('.', 1)
        if ext not in self.file_parsers:
            raise ValueError(f'Unsupported file format {ext}')

        try:
            with open(filepath, 'r') as f:
                data = self.file_parsers[ext](f)

            if not self._validate(data):
                self.logger.warning(f'Invalid data in {filepath}')
                return

        except Exception as e:
            self.logger.error(f'Error processing file {filepath}: {str(e)}')
            return

        # process the validated and parsed data here...

    def _parse_csv(self, f):
        reader = csv.DictReader(f)
        return [row for row in reader]

    def _parse_json(self, f):
        return json.load(f)

    def _parse_xml(self, f):
        return xmltodict.parse(f.read())

class MultiThreadedDataProcessor:
    def __init__(self):
        self.processor = DataProcessor()
        self.queue = Queue()
        self.pool = Pool()

    def process_files(self, filepaths):
        for filepath in filepaths:
            self.queue.put(filepath)

        while not self.queue.empty():
            self.pool.apply_async(self.processor.process, args=[self.queue.get()])

        # Wait until all tasks have been processed...
        self.pool.close()
        self.pool.join()
```
This code is a simplification and does not fully address your requirements (e.g., memory pooling, retry logic, configuration options). However, it should give you a good starting point on how to approach this problem in Python. 

